237	/**
238	 * A claim's due figure, as the screen shows it: the due fixed when it was settled, else the figure
239	 * its person's last statement bound it to (never while it is PENDING), else its live due: its amount times its grade's rate in
240	 * force on its date, divided by 100 and rounded to two decimals, raised to the sheet's floor when
241	 * below it (a correction, a negative amount, has no floor and no late charge). Null for n/a (no
242	 * floor applies to n/a). Every rounding of a claim's live figures is by the sheet's policy date
243	 * ({@link Settings#rounding}): half up when the claim is dated before it, half to even on or after;
244	 * a correction rounds by the date of the claim it corrects.
245	 */
246	public final class ClaimFigure {
247	    private ClaimFigure() {}
248	    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
249	        if (claim.getSettledDue() != null) return claim.getSettledDue();
250	        if (claim.isBound()) return claim.getStatedDue();
251	        return live(claim, rates, grade, settings, today);
252	    }
253	    /** The claim's live due at its grade's rate on its date; a correction has no floor. */
254	    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
255	        RoundingMode mode = rounding(claim, settings, today);
256	        return Rate.inForce(rates, grade, claim.getDate())
257	                .map((pct) -> times(claim.getAmount(), pct, mode))
258	                .map((due) -> claim.isCorrection() ? due : due.max(settings.floorOn(claim.getDate())))
259	                .orElse(null);
260	    }
261	    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
262	    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
263	        return settings.rounding(claim.getRoundDate(), today);
264	    }
265	    /**
266	     * The claim's due with its late charge on top: its figure ({@link #of}) plus the late charge
267	     * an OPEN or PENDING claim gains while overdue on {@code today}. Null for n/a.
268	     */
269	    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
270	            LocalDate today) {
271	        BigDecimal figure = of(claim, rates, grade, settings, today);
272	        return figure == null ? null : figure.add(late(claim, figure, settings, today));
273	    }
274	    /**
275	     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
276	     * on {@code today}, the sheet's late percent of the figure for every full 30 days it is
277	     * overdue, rounded to two decimals as the claim rounds; else 0.00 (as for a claim deferred on today). Never bound by a statement:
278	     * it follows the sheet's today until the claim is settled.
279	     */
280	    public static BigDecimal late(Claim claim, BigDecimal figure, Settings settings, LocalDate today) {
281	        if (!claim.isOpen() || claim.isDeferredOn(today)) return BigDecimal.ZERO.setScale(2);
282	        return lateAsOpen(claim, figure, settings, today);
283	    }
284	    /** The late charge on a figure as {@link #late} reads it for an open claim, whatever the claim's status. */
285	    public static BigDecimal lateAsOpen(Claim claim, BigDecimal figure, Settings settings, LocalDate today) {
286	        BigDecimal none = BigDecimal.ZERO.setScale(2);
287	        if (figure == null || claim.isCorrection()) return none;
288	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
289	        long periods = overdue > 0 ? overdue / 30 : 0;
290	        if (periods == 0) return none;
291	        return figure.multiply(settings.latePctOn(claim.getDate())).multiply(BigDecimal.valueOf(periods))
292	                .divide(BigDecimal.valueOf(100), 2, rounding(claim, settings, today));
293	    }
294	    /** The amount times the percent, divided by 100 and rounded to two decimals. */
295	    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
296	        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
297	    }
298	}
