300	/**
301	 * A validated claim request. {@code date} is null when left blank: the sheet's today.
302	 * {@code corrects} is the number of the claim a correction (a negative amount) corrects; null for
303	 * any other claim.
304	 */
305	public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects) {
306	    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");
307	    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|.{1,190}-\\d{1,9}");
308	    /** A claim request checked by the claim form's rules. */
309	    public static ClaimInput from(ClaimRequest request) throws InvalidClaimException {
310	        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
311	        if (amount.isEmpty()) throw new InvalidClaimException("An amount is required");
312	        if (!AMOUNT.matcher(amount).matches()) {
313	            throw new InvalidClaimException("An amount is a number with up to two decimals");
314	        }
315	        String rawDate = request.date() == null ? "" : request.date().trim();
316	        LocalDate date = null;
317	        if (!rawDate.isEmpty()) {
318	            try {
319	                date = LocalDate.parse(rawDate);
320	            } catch (DateTimeParseException e) {
321	                throw new InvalidClaimException("A date is yyyy-MM-dd");
322	            }
323	        }
324	        String note = request.note() == null ? "" : request.note().trim();
325	        if (note.length() > 1000) throw new InvalidClaimException("A note is at most 1000 characters");
326	        BigDecimal value = new BigDecimal(amount).setScale(2);
327	        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
328	        String corrects = null;
329	        if (value.signum() < 0) {
330	            if (rawCorrects.isEmpty()) {
331	                throw new InvalidClaimException("A negative amount is a correction: name the claim it corrects");
332	            }
333	            if (!NUMBER.matcher(rawCorrects).matches()) {
334	                throw new InvalidClaimException("A correction names a claim by its number");
335	            }
336	            corrects = rawCorrects;
337	        } else if (!rawCorrects.isEmpty()) {
338	            throw new InvalidClaimException("Only a negative amount corrects a claim");
339	        }
340	        return new ClaimInput(value, date, note, corrects);
341	    }
342	}
