518	/**
519	 * Opens the selected claims in list order (people in the order they were added, each person's
520	 * claims newest first), numbering each as it is opened. A claim that cannot be opened (not a
521	 * draft, dated inside a closed period, not on the sheet) is refused and left as it is. Each claim
522	 * opened is logged and audited as a single open is: its CLAIM_OPENED line, then the figures it moved.
523	 */
524	public class OpenSelectedClaims {
525	    public void open(@Val Sheet sheet, @Val BulkOpenRequest request, ClaimRepository claims,
526	            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
527	            SettingsRepository settings, ClaimLogRepository log, HttpServletRequest http, Audit audit,
528	            Out<BulkOpenResponse> result) {
529	        String user = Audit.user(http);
530	        Set<Long> selected = new HashSet<>();
531	        for (String id : request.claimIds()) {
532	            try {
533	                selected.add(Long.parseLong(id.trim()));
534	            } catch (NumberFormatException | NullPointerException e) {
535	                // not an id: no claim on the sheet, so refused below
536	            }
537	        }
538	        int requested = new HashSet<>(request.claimIds()).size();
539	        int opened = 0;
540	        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
541	        for (Person person : people.findAll(sheet.id())) {
542	            List<Claim> theirs = claims.findByPerson(sheet.id(), person.getId());
543	            for (Claim claim : theirs) {
544	                if (!selected.contains(claim.getId())) continue;
545	                if (!opens(sheet, claim, periods, claims)) continue;
546	                claim.setOpenedBy(user);
547	                claim.setNumber(ClaimNumbers.next(sheet, claim, settings.find(sheet.id()), periods, claims));
548	                claims.save(claim);
549	                log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
550	                opened++;
551	                audit.record(ClaimAudit.line(claim.getStatus().auditEvent(), sheet, user, person, claim));
552	                Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
553	                after.changesSince(before, sheet.id(), user).forEach(audit::record);
554	                before = after;
555	            }
556	        }
557	        result.set(new BulkOpenResponse(opened, requested - opened));
558	    }
559	    /** Moves the claim to OPEN when its status and period allow it and no one opened it first. */
560	    private static boolean opens(Sheet sheet, Claim claim, PeriodRepository periods, ClaimRepository claims) {
561	        if (periods.closedOn(sheet.id(), claim.getDate()) != null) return false;
562	        try {
563	            claim.moveTo(ClaimStatus.OPEN);
564	        } catch (InvalidClaimStatusException e) {
565	            return false;
566	        }
567	        return claims.markOpened(claim);
568	    }
569	    private static Rollup rollup(Sheet sheet, SheetRepository sheets, PersonRepository people, ClaimRepository claims,
570	            RateRepository rates, SettingsRepository settings) {
571	        return Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates, settings.find(sheet.id()));
572	    }
