713	public class SettleClaim {
714	    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
715	            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
716	            throws InvalidClaimStatusException, SelfSettleException {
717	        settle(sheet, claim, Audit.user(request), people, rates, roles, settingsStore);
718	    }
719	    /** Settles the claim as the given user would, by the rules above; throws when it may not. */
720	    static void settle(Sheet sheet, Claim claim, String user, PersonRepository people, RateRepository rates,
721	            RoleRepository roles, SettingsRepository settingsStore)
722	            throws InvalidClaimStatusException, SelfSettleException {
723	        Person person = people.find(sheet.id(), claim.getPersonId());
724	        Settings settings = settingsStore.find(sheet.id());
725	        BigDecimal figure = claim.isStated() ? claim.getStatedDue()
726	                : ClaimFigure.live(claim, rates.findAll(sheet.id()), person.gradeOn(claim.getDate()), settings,
727	                        sheet.today());
728	        // The late charge is read while the claim is still OPEN.
729	        BigDecimal late = ClaimFigure.late(claim, figure, settings, sheet.today());
730	        if (claim.isDeferredOn(sheet.today())) {
731	            throw new InvalidClaimStatusException("A claim deferred until " + claim.getDeferredUntil() + " cannot be settled");
732	        }
733	        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
734	            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
735	        }
736	        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
737	        BigDecimal due = figure == null ? null : figure.add(late);
738	        if (!settings.withinClerkLimit(due, sheet.today()) && Role.CLERK.equals(roles.roleOf(sheet.id(), user))) {
739	            claim.moveTo(ClaimStatus.PENDING);
740	            return;
741	        }
742	        claim.moveTo(ClaimStatus.SETTLED);
743	        claim.setSettledDue(due);
744	    }
