747	/**
748	 * Settles the selected claims in list order (people in the order they were added, each person's
749	 * claims newest first) by exactly the rules of settling one claim, as the signed-in user. A claim
750	 * sent to PENDING counts as settled; a claim that cannot be settled (its status does not allow it,
751	 * dated inside a closed period, opened by this user, not on the sheet) is refused and left as it is.
752	 * Each claim settled is logged and audited as a single settle is: its status line, then the
753	 * figures it moved.
754	 */
755	public class SettleSelectedClaims {
756	    public void settle(@Val Sheet sheet, @Val BulkSettleRequest request, ClaimRepository claims,
757	            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
758	            RoleRepository roles, SettingsRepository settings, ClaimLogRepository log, HttpServletRequest http,
759	            Audit audit, Out<BulkSettleResponse> result) {
760	        String user = Audit.user(http);
761	        Set<Long> selected = new HashSet<>();
762	        for (String id : request.claimIds()) {
763	            try {
764	                selected.add(Long.parseLong(id.trim()));
765	            } catch (NumberFormatException | NullPointerException e) {
766	                // not an id: no claim on the sheet, so refused below
767	            }
768	        }
769	        int requested = new HashSet<>(request.claimIds()).size();
770	        int settled = 0;
771	        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
772	        for (Person person : people.findAll(sheet.id())) {
773	            for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
774	                if (!selected.contains(claim.getId())) continue;
775	                if (periods.closedOn(sheet.id(), claim.getDate()) != null) continue;
776	                try {
777	                    SettleClaim.settle(sheet, claim, user, people, rates, roles, settings);
778	                } catch (InvalidClaimStatusException | SelfSettleException e) {
779	                    continue;
780	                }
781	                claims.save(claim);
782	                log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
783	                settled++;
784	                audit.record(AuditClaimStatus.line(sheet, claim, user, people));
785	                Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
786	                after.changesSince(before, sheet.id(), user).forEach(audit::record);
787	                before = after;
788	            }
789	        }
790	        result.set(new BulkSettleResponse(settled, requested - settled));
791	    }
792	    private static Rollup rollup(Sheet sheet, SheetRepository sheets, PersonRepository people, ClaimRepository claims,
793	            RateRepository rates, SettingsRepository settings) {
794	        return Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates, settings.find(sheet.id()));
795	    }
796	}
