580	/**
581	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total (by person id,
582	 * in the order they were added), and the sheet's claimed-total, due-total and overdue-total.
583	 */
584	public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
585	    /** A person's figures: their name, claimed, due-total (n/a when none) and overdue-total. */
586	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
587	        boolean sameFigures(Figures other) {
588	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
589	                    && overdueTotal.equals(other.overdueTotal);
590	        }
591	    }
592	    /**
593	     * The sheet's figures now. A person's claimed is the amounts of their claims that count (OPEN
594	     * and SETTLED, but not an unbound OPEN one dated within one of their holds) added up; their due-total the figures of those claims added up, skipping n/a (a live figure is at least the sheet's floor; an overdue one gains its late
595	     * charge on {@code today}), and
596	     * n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
597	     * figure or has one under the grade in force on its date when that is another grade, or
598	     * has one dated on or before today (under a rate that has since ended), held to the sheet's cap. Each claim
599	     * takes the rate of the grade in force on its date. The
600	     * sheet's totals add these up, skipping n/a.
601	     */
602	    public static Rollup of(String sheetId, LocalDate today, PersonRepository people, ClaimRepository claims,
603	            RateRepository rates, Settings settings) {
604	        List<Rate> all = rates.findAll(sheetId);
605	        List<Claim> sheetClaims = claims.findAll(sheetId);
606	        Map<Long, Figures> figures = new LinkedHashMap<>();
607	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
608	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
609	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
610	        for (Person person : people.findAll(sheetId)) {
611	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
612	            BigDecimal due = BigDecimal.ZERO.setScale(2);
613	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
614	            boolean fixed = false;
615	            for (Claim claim : sheetClaims) {
616	                if (claim.getPersonId() != person.getId()) continue;
617	                if (!claim.counts(person.heldOn(claim.getDate()), today)) continue;
618	                claimed = claimed.add(claim.getAmount());
619	                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
620	                String grade = person.gradeOn(claim.getDate());
621	                BigDecimal figure = ClaimFigure.withLate(claim, all, grade, settings, today);
622	                if (figure != null) due = due.add(figure);
623	                if (figure != null && overdue(claim, today)) overdue = overdue.add(figure);
624	                // A figure found under a grade other than today's is kept, whatever today's rate.
625	                if (figure != null && !grade.equals(person.gradeOn(today))) fixed = true;
626	                // So is one dated on or before today, found under a rate that has since ended.
627	                if (figure != null && !claim.getDate().isAfter(today)) fixed = true;
628	            }
629	            boolean none = Rate.inForce(all, person.gradeOn(today), today).isEmpty() && !fixed;
630	            claimedTotal = claimedTotal.add(claimed);
631	            overdueTotal = overdueTotal.add(overdue);
632	            due = settings.capped(due, today);
633	            if (!none) dueTotal = dueTotal.add(due);
634	            figures.put(person.getId(), new Figures(person.getName(), show(claimed), none ? "n/a" : show(due),
635	                    show(overdue)));
636	        }
637	        return new Rollup(figures, show(claimedTotal), show(dueTotal), show(overdueTotal));
638	    }
639	    /** Whether a claim is overdue on {@code today}: open (OPEN or PENDING) and past its due-by. */
640	    private static boolean overdue(Claim claim, LocalDate today) {
641	        return claim.isOpen() && today != null && claim.getDueBy() != null && claim.getDueBy().isBefore(today);
642	    }
643	    /**
644	     * The audit lines for the move from {@code before} to this: one ROLLUP line per person whose
645	     * figures changed (a person new since counts as changed), then a TOTALS line when any of the
646	     * sheet's three totals changed.
647	     */
648	    public List<String> changesSince(Rollup before, String sheetId, String user) {
649	        List<String> lines = new ArrayList<>();
650	        String head = " sheet=" + sheetId + " by=" + user;
651	        people.forEach((id, now) -> {
652	            if (!now.sameFigures(before.people().get(id))) {
653	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
654	                        + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
655	            }
656	        });
657	        if (!claimedTotal.equals(before.claimedTotal()) || !dueTotal.equals(before.dueTotal())
658	                || !overdueTotal.equals(before.overdueTotal())) {
659	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
660	                    + " overdue-total=" + overdueTotal);
661	        }
662	        return lines;
663	    }
664	    private static String show(BigDecimal value) {
665	        return value.setScale(2).toPlainString();
666	    }
667	}
