693	/**
694	 * Takes the person's statement: their due-total now (the figures of their claims that count, added
695	 * up, skipping n/a; n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
696	 * figure, has one under another grade in force on its date, or has one dated on or before today (under a
697	 * rate that has since ended); held to the sheet's cap; each claim at its date's grade's rate; an overdue claim's late charge on top), as the screen shows it. Every claim of theirs that counts is bound to its figure now (a live
698	 * one at least the sheet's floor), never its late charge;
699	 * every other claim of theirs is left unbound (live). The person's statement count goes up by one,
700	 * and the due-total and the sheet's today are kept as the last statement's.
701	 */
702	public class TakeStatement {
703	    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates,
704	            SettingsRepository settings, PersonRepository people, Out<Statement> statementOut) {
705	        List<Rate> all = rates.findAll(sheet.id());
706	        Settings sheetSettings = settings.find(sheet.id());
707	        BigDecimal total = BigDecimal.ZERO.setScale(2);
708	        boolean fixed = false;
709	        int counted = 0;
710	        for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
711	            boolean counts = claim.counts(person.heldOn(claim.getDate()), sheet.today());
712	            if (counts) {
713	                counted++;
714	                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
715	                String grade = person.gradeOn(claim.getDate());
716	                BigDecimal figure = ClaimFigure.of(claim, all, grade, sheetSettings, sheet.today());
717	                // A figure found under a grade other than today's is kept, whatever today's rate.
718	                if (figure != null && !grade.equals(person.gradeOn(sheet.today()))) fixed = true;
719	                // So is one dated on or before today, found under a rate that has since ended.
720	                if (figure != null && !claim.getDate().isAfter(sheet.today())) fixed = true;
721	                // The due-total carries the late charge; the claim is bound to the figure under it.
722	                if (figure != null) total = total.add(figure).add(ClaimFigure.late(claim, figure, sheetSettings, sheet.today()));
723	                claim.bind(true, figure);
724	            } else {
725	                claim.bind(false, null);
726	            }
727	            claims.save(claim);
728	        }
729	        String dueTotal = Rate.inForce(all, person.gradeOn(sheet.today()), sheet.today()).isEmpty() && !fixed
730	                ? "n/a" : sheetSettings.capped(total, sheet.today()).toPlainString();
731	        person.setStatements(person.getStatementCount() + 1, dueTotal, sheet.today());
732	        people.saveStatements(person);
733	        statementOut.set(new Statement(dueTotal, counted));
