235	@Repository
236	public class PersonRepository {
237	    private static final String COLUMNS = "id, sheet_id, name, grade, version, statement_count, stated_total, statement_date, retired_from";
238	    private static final RowMapper<Person> ROW = (rs, n) -> {
239	        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
240	                rs.getString("grade"), rs.getLong("version"));
241	        person.setStatements(rs.getInt("statement_count"), rs.getString("stated_total"),
242	                rs.getObject("statement_date", LocalDate.class));
243	        person.setRetiredFrom(rs.getObject("retired_from", LocalDate.class));
244	        return person;
245	    };
246	    private final JdbcTemplate jdbc;
247	    public PersonRepository(JdbcTemplate jdbc) {
248	        this.jdbc = jdbc;
249	    }
250	    /** The sheet's people, in the order they were added. */
251	    public List<Person> findAll(String sheetId) {
252	        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
253	                ROW, sheetId);
254	        Map<Long, Person> byId = new HashMap<>();
255	        people.forEach((p) -> byId.put(p.getId(), p));
256	        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ?",
257	                (rs) -> {
258	                    Person person = byId.get(rs.getLong("person_id"));
259	                    if (person != null) person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
260	                }, sheetId);
261	        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY person_id, patron_id",
262	                (rs) -> {
263	                    Person person = byId.get(rs.getLong("person_id"));
264	                    if (person != null) person.getPatronIds().add(rs.getLong("patron_id"));
265	                }, sheetId);
266	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id",
267	                (rs) -> {
268	                    Person person = byId.get(rs.getLong("person_id"));
269	                    if (person != null) person.getHolds().add(hold(rs));
270	                }, sheetId);
271	        return people;
272	    }
273	    /** The person with this id on the sheet, or null when there is none. */
274	    public Person find(String sheetId, long id) {
275	        List<Person> found = jdbc.query(
276	                "SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
277	                ROW, sheetId, id);
278	        if (found.isEmpty()) return null;
279	        Person person = found.get(0);
280	        loadGrades(person);
281	        loadHolds(person);
282	        person.getPatronIds().addAll(jdbc.queryForList(
283	                "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY patron_id",
284	                Long.class, sheetId, id));
285	        return person;
286	    }
287	    /** Record {@code patron} as one of the person's patrons. */
288	    public void addPatron(Person person, Person patron) {
289	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) VALUES (?, ?, ?)",
290	                person.getSheetId(), person.getId(), patron.getId());
291	        person.getPatronIds().add(patron.getId());
292	    }
293	    /** The person on the sheet with this name, ignoring case and surrounding spaces, or null when there is none. */
294	    public Person findByName(String sheetId, String name) {
295	        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ?"
296	                + " AND LOWER(TRIM(name)) = LOWER(TRIM(?)) ORDER BY id", ROW, sheetId, name);
297	        if (found.isEmpty()) return null;
298	        loadGrades(found.get(0));
299	        loadHolds(found.get(0));
300	        return found.get(0);
301	    }
302	    private void loadGrades(Person person) {
303	        jdbc.query("SELECT from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
304	                (rs) -> {
305	                    person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
306	                }, person.getSheetId(), person.getId());
307	    }
308	    private void loadHolds(Person person) {
309	        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ? ORDER BY id",
310	                (rs) -> {
311	                    person.getHolds().add(hold(rs));
312	                }, person.getSheetId(), person.getId());
313	    }
314	    private static Hold hold(java.sql.ResultSet rs) throws java.sql.SQLException {
315	        return new Hold(rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class));
316	    }
317	    /** Record the person's dated grades as they hold them now, replacing those stored. */
318	    private void saveGrades(Person person) {
319	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?",
320	                person.getSheetId(), person.getId());
321	        person.getDatedGrades().forEach((from, grade) -> jdbc.update(
322	                "INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
323	                person.getSheetId(), person.getId(), Date.valueOf(from), grade));
324	    }
325	    /** Whether a person other than {@code exceptId} has this name on the sheet, ignoring case. */
326	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
327	        Integer count = jdbc.queryForObject(
328	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
329	                        + " AND id <> ?",
330	                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
331	        return count != null && count > 0;
332	    }
333	    /** Record the person's statements (their count, last due-total and date), leaving the rest as stored. */
334	    public void saveStatements(Person person) {
335	        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE id = ? AND sheet_id = ?",
336	                person.getStatementCount(), person.getStatedTotal(),
337	                person.getStatementDate() == null ? null : Date.valueOf(person.getStatementDate()),
338	                person.getId(), person.getSheetId());
339	    }
340	    /** Record the date the person is retired from, leaving the rest as stored. */
341	    public void saveRetired(Person person) {
342	        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?",
343	                person.getRetiredFrom() == null ? null : Date.valueOf(person.getRetiredFrom()),
344	                person.getId(), person.getSheetId());
345	    }
346	    /** Record a new hold on the person, leaving the rest as stored. */
347	    public void addHold(Person person, Hold hold) {
348	        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
349	                person.getSheetId(), person.getId(), Date.valueOf(hold.from()),
350	                hold.to() == null ? null : Date.valueOf(hold.to()));
351	    }
352	    /**
353	     * Insert a new person (assigning its id) or update an existing one, raising its version. False
354	     * when the stored person is no longer at the version it was loaded at: nothing is written.
355	     */
356	    public boolean save(Person person) {
357	        if (person.getId() != null) {
358	            int updated = jdbc.update("UPDATE person SET name = ?, grade = ?, version = version + 1"
359	                    + " WHERE id = ? AND sheet_id = ? AND version = ?",
360	                    person.getName(), person.getGrade(), person.getId(), person.getSheetId(),
361	                    person.getVersion());
362	            if (updated == 0) return false;
363	            person.setVersion(person.getVersion() + 1);
364	            saveGrades(person);
365	            return true;
366	        }
367	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
368	        jdbc.update(con -> {
369	            PreparedStatement ps = con.prepareStatement(
370	                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)",
371	                    Statement.RETURN_GENERATED_KEYS);
372	            ps.setString(1, person.getSheetId());
373	            ps.setString(2, person.getName());
374	            ps.setString(3, person.getGrade());
375	            return ps;
376	        }, keys);
377	        person.setId(keys.getKey().longValue());
378	        saveGrades(person);
379	        return true;
380	    }
381	}
