556	/**
557	 * Closes the period, fixing its due-total at this moment: the figures of the claims that count (OPEN
558	 * and SETTLED, but not an unbound OPEN one dated within a hold of its person) dated inside it (an overdue one with its late charge), added up, skipping n/a. Each person's own figure for the period is fixed
559	 * too, and the period's due-total is the sum of them. A period already closed is refused.
560	 */
561	public class ClosePeriod {
562	    public void close(@Val Sheet sheet, @Val Period period, PeriodRepository periods, PersonRepository people,
563	            ClaimRepository claims, RateRepository rates, SettingsRepository settings, Out<Period> closedOut) throws InvalidPeriodException {
564	        if (period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
565	        List<Rate> all = rates.findAll(sheet.id());
566	        Settings sheetSettings = settings.find(sheet.id());
567	        List<Claim> sheetClaims = claims.findAll(sheet.id());
568	        BigDecimal total = BigDecimal.ZERO.setScale(2);
569	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
570	        for (Person person : people.findAll(sheet.id())) {
571	            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
572	            for (Claim claim : sheetClaims) {
573	                if (claim.getPersonId() != person.getId() || !period.contains(claim.getDate())) continue;
574	                if (!claim.counts(person.heldOn(claim.getDate()), sheet.today())) continue;
575	                BigDecimal figure = ClaimFigure.withLate(claim, all, person.gradeOn(claim.getDate()), sheetSettings, sheet.today());
576	                if (figure != null) personTotal = personTotal.add(figure);
577	            }
578	            personTotals.put(person.getId(), personTotal);
579	            total = total.add(personTotal);
580	        }
581	        Period closed = period.close(total);
582	        if (!periods.markClosed(closed)) {
583	            throw new InvalidPeriodException("Period " + period.name() + " is already closed");
584	        }
585	        periods.savePersonTotals(closed, personTotals);
586	        closedOut.set(closed);
587	    }
588	}
