/** Due values added up, skipping n/a. */
export function sumDue(values: string[]): string {
  return showCents(values.filter((v) => v !== NA).reduce((n, v) => n + hundredths(v), 0n));
}

/**
 * A claim's due: the one fixed when it was settled (its late charge frozen in), else the figure its
 * person's last statement bound it to (never while it is PENDING), else its amount at the rate in force on its date, at least
 * the sheet's `floor` in force on its date; an overdue claim's late charge added on top.
 */
export function claimDue(claim: Claim, pct: string | null, floor: Dated, late: Late): string {
  if (claim.due !== '') return claim.due;
  const least = isCorrection(claim) ? null : valueOn(floor, claim.date);
  const figure = isBound(claim) ? claim.statedDue : due(claim.amount, pct, least, roundsHalfUp(claim, late));
  const charge = lateCharge(claim, figure, late);
  return charge === 0n ? figure : showCents(hundredths(figure) + charge);
}

/**
 * A person's due-total: the figures of their claims that count (an unbound OPEN one not when dated within one of their `holds`) (each at the rate in force on its
 * date for their grade in force on its date), added up, skipping n/a. With no rate for their grade
 * today it is n/a, unless a claim that counts keeps a fixed figure (settled, or bound by a
 * statement), has a figure under another grade in force on its date, or has a figure dated on or
 * before today (under a rate that has since ended). Held to the sheet's `cap` ('' for none); n/a is
 * not capped.
 */
export function personDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  cap: string,
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late);
  if (total === NA || cap === '' || hundredths(total) <= hundredths(cap)) return total;
  return showCents(hundredths(cap));
}

/** How far a person's due-total, before the sheet's `cap` ('' for none), goes above it: 0.00 when it does not. */
export function personExcess(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  cap: string,
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late);
  if (total === NA || cap === '' || hundredths(total) <= hundredths(cap)) return '0.00';
  return showCents(hundredths(total) - hundredths(cap));
}

function uncappedDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
): string {
  const counted = claims.filter((c) => counts(c, holds, today));
  const grade = gradeOn(grades, today);
  const kept = (c: Claim) => c.due !== '' || (isBound(c) && c.statedDue !== NA)
    || (gradeOn(grades, c.date) !== grade && rateOn(rates, gradeOn(grades, c.date), c.date) !== null)
    || (c.date <= today && rateOn(rates, gradeOn(grades, c.date), c.date) !== null);
  if (rateOn(rates, grade, today) === null && !counted.some(kept)) return NA;
  return sumDue(counted.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late)));
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn } from '../people/people';
import type { Hold } from '../people/people';

/**
 * A claim's status: DRAFT when made, then OPEN, then SETTLED; a clerk's settle above the clerk
 * limit makes it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
 * OPEN or PENDING claim may be VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/**
 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
 * number on the sheet (given when it is opened; '' for a draft or a voided claim), and its due as
 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate), and
 * who opened it ('' until it is opened); whether its person's last statement bound it, and the
 * figure it was bound to ('' when not stated; n/a when it had none); and, for a correction (a
 * negative amount), the number of the settled claim it corrects ('' for any other claim); and the
 * date (yyyy-MM-dd) its figures round by (a correction's is the date of the claim it corrects).
 */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  openedBy: string;
  stated: boolean;
  statedDue: string;
  corrects: string;
  roundDate: string;
  /** Its due-by (yyyy-MM-dd), fixed when it was made: its date plus its grade's terms then. */
  dueBy: string;
  /**
   * Its status log, oldest first: one line per status it has had, as
   * `<STATUS> by <user> on <date> due=<due>` (the sheet's today and its due at that moment).
   */
  log: string[];
  /** The date (yyyy-MM-dd) it is deferred until; '' when it was never deferred. */
  deferredUntil: string;
};

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim's stated figure is in force: its person's last statement bound it and it is not
 * PENDING (a PENDING claim shows its live figure).
 */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/**
 * Whether a claim is deferred on the sheet's `today`: OPEN and deferred until a date after today.
 * From that date on it is an OPEN claim like any other.
 */
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== '' && today !== '' && today < c.deferredUntil;

/**
 * Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED
 * do, and an OPEN or PENDING one not when it is dated within one of its person's `holds`, unless a
 * statement binds it; never one deferred on `today`.
 */
export const counts = (c: Claim, holds: Hold[], today: string) =>
  !isDeferred(c, today) && (c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds, c.date))));

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: async () =>
    (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
});

/** The sheet's claims, newest first. */
export function useClaims(sheetId: string) {
  return useQuery(claimsQuery(sheetId));
}

/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** An amount as the claim form takes it: up to two decimals, negative for a correction. */
export const CLAIM_AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/**
 * A claim number, as a correction names the claim it corrects: a sheet-wide number, or a number
 * within a period (<period name>-<n>, X-<n> for a claim in no period).
 */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/**
 * The amounts of the claims that count (OPEN, PENDING and SETTLED, but not unbound open ones dated within
 * a hold of their person: `holds` tells by person id, nor ones deferred on `today`) added up, in whole cents so no rounding creeps in, shown with two
 * decimals.
 */
export function sumAmounts(claims: Claim[], holds: (personId: string) => Hold[], today: string): string {
  const cents = claims.filter((c) => counts(c, holds(c.personId), today)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade in force from a date (yyyy-MM-dd; '' from the beginning of time) until the next one. */
export type GradeFrom = { from: string; grade: Grade };

/** The grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): Grade {
  let best = grades[0];
  for (const g of grades) if (g.from <= date && g.from >= best.from) best = g;
  return best.grade;
}

// `version` is raised by each save; an edit sends the version it was made from. `statementCount`
// is how many statements have been taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and date ('' before the first). `retired` is set once they have a retirement
// date, `retiredFrom` ('' when not retired), whatever that date is. `held` is whether they have any hold; `holds` their holds in the order added (see `Hold`).
// `patronIds` are the ids of the people they name as their patrons. `grade` is the grade in force on
// the sheet's today; `grades` every grade they have been given, by from-date, the first from ''.
export type Person = {
  id: string;
  name: string;
  grade: Grade;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: Hold[];
  patronIds: string[];
  grades: GradeFrom[];
};

/**
 * A hold on a person: from a date to a date (yyyy-MM-dd; `to` '' when open-ended), both inclusive.
 * An OPEN or PENDING claim of theirs dated within one, unless a statement binds it, counts in no total.
 */
export type Hold = { from: string; to: string };

/** Whether the date (yyyy-MM-dd) is within one of the holds. */
export const heldOn = (holds: Hold[], date: string) =>
  holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: async () =>
    (await getJson<{ people: Person[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people`)).people,
});

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery(peopleQuery(sheetId));
}

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet keeps it. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { gradeOn } from '../people/people';
import type { GradeFrom, Hold } from '../people/people';
import { counts, isDeferred, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/** A claim's due-by: fixed when it was made, from its grade's terms then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/**
 * Whether a claim is overdue: open (OPEN or PENDING), not deferred, and its due-by before the
 * sheet's `today`.
 */
export const isOverdue = (claim: Claim, today: string): boolean =>
  isOpen(claim) && !isDeferred(claim, today) && today !== '' && dueBy(claim) < today;

/**
 * A person's overdue claims that count (not an unbound OPEN one dated within one of their `holds`, as it then counts in
 * no total): how many, and their due figures (with their late charge) added up, skipping n/a.
 */
export function personOverdue(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
): { count: number; total: string } {
  const overdue = claims.filter((c) => counts(c, holds, today) && isOverdue(c, today));
  return {
    count: overdue.length,
    total: sumDue(overdue.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late))),
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Dated, Late } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';

/**
 * A sheet's settings: its clerk limit, with two decimals ('' for no limit), and its floor, the
 * least a claim's live due may be, with two decimals, and its terms, the whole number of days after a
 * claim's date that it is due by, and its late percent, what an overdue claim's due gains per full 30
 * days overdue, with two decimals, and its policy date (yyyy-MM-dd; '' for the sheet's today): a claim
 * dated before it rounds half up, one on or after it half to even, and its period numbering from
 * (yyyy-MM-dd; '' for off): while the sheet's today is on or after it, a claim opened is numbered
 * within its period.
 */
export type Settings = {
  clerkLimit: string;
  floor: string;
  terms: string;
  latePct: string;
  policyDate: string;
  periodNumberingFrom: string;
  /** Each grade's own terms in days ('' for the sheet's terms). */
  gradeTerms: Record<string, string>;
  /** The most a person's due-total may be, with two decimals ('' for none). */
  cap: string;
  /**
   * Every value recorded for each figure setting, by key (clerk-limit, floor, terms, late-pct,
   * terms-A, terms-B, terms-C, cap), in from-date order ('' for none). The values above are those
   * in force on the sheet's today.
   */
  dated?: Record<string, { from: string; value: string }[]>;
};

/** The figure settings, which are saved from a from-date, by the key the screen and the store use. */
export const DATED_KEYS = {
  clerkLimit: 'clerk-limit',
  floor: 'floor',
  terms: 'terms',
  latePct: 'late-pct',
  cap: 'cap',
} as const;

/** The grades that may have their own terms. */
export const GRADES = ['A', 'B', 'C'] as const;

/** A save of the settings: only those being changed are sent. */
export type SettingsChange = Partial<Omit<Settings, 'dated'>> & { from?: Record<string, string> };

/** A user's role on a sheet. A name with no role assigned is a clerk. */
export type Role = { user: string; role: string };

export const ROLES = ['clerk', 'steward'] as const;

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;
export const rolesKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;

export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/**
 * The sheet's floor, dated: 1.00 before every value recorded, each claim taking the one in force on
 * its date ('0.00', no floor, until the settings are read).
 */
export function useFloor(sheetId: string): Dated {
  const settings = useSettings(sheetId).data;
  if (!settings) return { start: '0.00', values: [] };
  return { start: '1.00', values: settings.dated?.floor ?? [] };
}

/**
 * What the sheet's late charge and rounding need: its late percent ('0.00' until read),
 * today and policy date ('' until read).
 */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId).data;
  const pct: Dated = { start: '0.00', values: settings?.dated?.['late-pct'] ?? [] };
  return { pct, today: useSheetToday(sheetId), policyDate: settings?.policyDate ?? '' };
}

/** The sheet's cap on a person's due-total ('' for none, until the settings are read). */
export function useCap(sheetId: string): string {
  return useSettings(sheetId).data?.cap ?? '';
}

/** The roles assigned on the sheet, by user name. */
export function useRoles(sheetId: string) {
  return useQuery({
    queryKey: rolesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ roles: Role[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`)).roles,
  });
}

/** A clerk limit as the screen takes it: blank, or 0.00 or more with up to two decimals. */
export const LIMIT = /^\d+(\.\d{1,2})?$/;

/** A cap as the screen takes it: blank, or 0.00 or more with up to two decimals. */
export const CAP = /^\d+(\.\d{1,2})?$/;

/** A floor as the screen takes it: 0.00 or more with up to two decimals. */
export const FLOOR = /^\d+(\.\d{1,2})?$/;

/** A late percent as the screen takes it: 0.00 or more with up to two decimals. */
export const LATE_PCT = /^\d+(\.\d{1,2})?$/;

/** A policy date as the screen takes it: blank, or a date yyyy-MM-dd. */
export const POLICY_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Terms as the screen takes them: a whole number of days, 0 or more. */
export const TERMS = /^\d{1,5}$/;
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { gradeOn } from '../people/people';
import type { Person } from '../people/people';
import { claimDue, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/**
 * A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd), inclusive, whether
 * it is closed, the due-total fixed when it was closed ('' while open), and each person's due-total
 * fixed when it was closed, by person id (empty while open).
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  personTotals: Record<string, string>;
};

export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ periods: Period[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`)).periods,
  });
}

/** The period whose dates contain the date (yyyy-MM-dd), or null when none does. */
export function periodOf(periods: Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

/**
 * A person's due-total for a period: the one fixed when it was closed (0.00 for a person added
 * after), else the due of their claims that count whose date falls in it, added up.
 */
export function personPeriodDueTotal(
  period: Period,
  person: Person,
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  if (period.closed) return period.personTotals[person.id] ?? '0.00';
  return sumDue(
    claims
      .filter((c) => c.personId === person.id && counts(c, person.holds, late.today) && period.from <= c.date && c.date <= period.to)
      .map((c) => claimDue(c, rateOn(rates, gradeOn(person.grades, c.date), c.date), floor, late)),
  );
}

/** A period's due-total: the people's due-totals for it, added up. */
export function periodDueTotal(
  period: Period,
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  return sumDue(people.map((person) => personPeriodDueTotal(period, person, claims, rates, floor, late)));
}
import { useSyncExternalStore } from 'react';

// The claims ticked for a bulk action, by sheet: each claim row ticks or unticks its own, and the
// bulk bar reads them all. Kept outside React so rows in different person rows share it.
const selected = new Map<string, ReadonlySet<string>>();
const listeners = new Set<() => void>();
const NONE: ReadonlySet<string> = new Set();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function set(sheetId: string, next: ReadonlySet<string>) {
  selected.set(sheetId, next);
  listeners.forEach((l) => l());
}

/** The ids of the claims ticked on the sheet. */
export function useSelectedClaims(sheetId: string): ReadonlySet<string> {
  return useSyncExternalStore(subscribe, () => selected.get(sheetId) ?? NONE);
}

/** Tick (or untick) a claim. */
export function selectClaim(sheetId: string, claimId: string, on: boolean) {
  const next = new Set(selected.get(sheetId) ?? NONE);
  if (on) next.add(claimId);
  else next.delete(claimId);
  set(sheetId, next);
}

/** Untick every claim on the sheet. */
export function clearSelectedClaims(sheetId: string) {
  set(sheetId, NONE);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string; today: string };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

/** The loaded sheet: its id and its today (yyyy-MM-dd). */
export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
}

/**
 * The sheet's today. Every date-dependent decision and every default date on the screen uses this,
 * never the real clock (`new Date()`); '' until the sheet has been read.
 */
export function useSheetToday(sheetId: string): string {
  return useSheet(sheetId).data?.today ?? '';
}

